// GENERATED by SiteDash — do not edit by hand. Re-run `sitedash init` (mount) to refresh.
import { cookies } from "next/headers";
import { can, CTA_ACTIONS, LEAD_STATUSES, REDIRECT_STATUSES, SETTING_DEFS, type DashboardDeps, type Principal, type SettingKey } from "@sitedash/core";
import { DashboardApp } from "@sitedash/ui/app";
import {
  bootAccess, settingDef, styleTag, UI_LOCALES,
  type Boot, type BootSettingDef, type CanFn,
} from "@sitedash/ui";
import {
  COLLECTIONS, CONTENT_LOCALES, CTA_LABELS, GUIDES, isFirstRun, leadsHiddenFor,
  LEGACY_DEFAULTS, loadServerContext, PAGE_ROUTES, PREVIEW_URLS, SESSION_COOKIE,
  THEME_INPUT, TREE, UI_LOCALE,
} from "@/sitedash/server";

const API_PREFIX = "/api/sitedash";
const THEMES = ["light", "dark"] as const;

/**
 * The dashboard speaks Arabic and English in light and dark, so a real host must be
 * able to show all four. The chosen pair comes from the URL and is VALIDATED against
 * what SiteDash actually ships - an unknown value falls back to the site default,
 * never a guess. This is cosmetic: it selects strings and colours, not permissions.
 */
function pick<T extends string>(raw: string | string[] | undefined, allowed: readonly T[], fallback: T): T {
  const v = Array.isArray(raw) ? raw[0] : raw;
  return v && (allowed as readonly string[]).includes(v) ? (v as T) : fallback;
}

/**
 * core owns the setting allow-list; the dashboard owns the labels. Mapping it HERE (and
 * not baking it) means the picker can never offer a key the API will reject.
 */
function settingDefs(): BootSettingDef[] {
  return (Object.keys(SETTING_DEFS) as SettingKey[]).map((key) => {
    const def = SETTING_DEFS[key];
    return settingDef(key, def.kind, def.def, "enum" in def ? [...def.enum] : []);
  });
}

// The page is DATA only. It resolves the session, asks core's shipped can() the questions
// the screens would otherwise ask the API, and hands the client the ANSWERS as booleans.
// Nothing here grants anything: every read and write below is re-checked server-side.
export default async function SiteDashAdmin({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const query = await searchParams;
  const uiLocale = pick(query.lang, UI_LOCALES, UI_LOCALE);
  const theme = pick(query.theme, THEMES, "light");

  // No database configured is a REAL state (the site must still run from its baked
  // snapshot), so it renders the locked dashboard instead of throwing at the operator.
  let deps: DashboardDeps | null = null;
  try {
    deps = loadServerContext().deps;
  } catch {
    deps = null;
  }

  let principal: Principal | null = null;
  let user: { email: string; isOwner: boolean } | null = null;
  let csrfToken = "";
  let hiddenLeadFields: string[] = [];
  if (deps) {
    const rawToken = (await cookies()).get(SESSION_COOKIE)?.value;
    const found = rawToken ? await deps.auth.verifySession(rawToken) : null;
    if (found) {
      principal = await deps.auth.principalFor(found.user.id);
      user = { email: found.user.email, isOwner: found.user.isOwner };
      csrfToken = found.session.csrfToken ?? "";
      hiddenLeadFields = await leadsHiddenFor(found.user);
    }
  }

  // ONE permission call, bound to this request's session - the same can() the API runs.
  const allowed: CanFn = (action, resource, scope) => can(principal, action, resource, scope);
  const pages = TREE.map((p) => p.id);
  const access = bootAccess(allowed, {
    signedIn: user !== null,
    owner: user?.isOwner === true,
    pages,
    collections: COLLECTIONS.map((c) => c.id),
    contentLocales: CONTENT_LOCALES,
    leadsRedacted: hiddenLeadFields.length > 0,
  });

  // Rows for the pages THIS session may view. pageIds stays complete: the content screen
  // needs every manifest page so a {pages:["home"],locales:["ar"]} grant does not hide
  // the en rows of the very page the operator may edit.
  const tree = user ? TREE.filter((p) => allowed("view", "fields", { pages: [p.id] })) : [];

  const boot: Boot = {
    apiPrefix: API_PREFIX,
    uiLocale,
    uiLocales: [...UI_LOCALES],
    contentLocales: CONTENT_LOCALES,
    theme,
    email: user?.email ?? null,
    csrfToken,
    firstRun: deps ? await isFirstRun(deps) : false,
    nav: access.nav,
    perms: access.perms,
    tree,
    pageIds: pages,
    pageRoutes: PAGE_ROUTES,
    ctaLabels: CTA_LABELS,
    ctaActions: [...CTA_ACTIONS],
    leadStatuses: [...LEAD_STATUSES],
    redirectStatuses: [...REDIRECT_STATUSES],
    collections: COLLECTIONS,
    settingDefs: settingDefs(),
    guides: GUIDES,
    // The visual editor's preview frame: same-origin page paths baked from the scan,
    // so a run whose NEXT_PUBLIC_SITE_URL points at production still previews itself.
    // It shows the PUBLISHED page and the editor says exactly that — the installed
    // runtime is deliberately sync-over-baked-snapshot (that is what keeps the site up
    // when the DB is down), so drafts cannot reach a framed page render. See docs.
    previewUrls: PREVIEW_URLS,
    legacy: LEGACY_DEFAULTS,
  };

  return (
    <>
      <div dangerouslySetInnerHTML={{ __html: styleTag(THEME_INPUT) }} />
      <DashboardApp boot={boot} />
    </>
  );
}
